package com.aliothmoon.maafw.once;
import org.junit.Test;import java.nio.file.*;import static org.junit.Assert.*;
public class UiBoundPointsProtocolTest {
 private static final String N="0123456789abcdef0123456789abcdef";
 private NativeUiStructureProtocol.Report report(){return new NativeUiStructureProtocol.Report(N,100,200,250,NativeUiStructureProtocol.Reason.OK,NativeUiStructureProtocol.Cleanup.CONFIRMED,3,20,1,0,0,0,100,100,-1,-1,NativeUiStructureProtocol.Task.unknown(),new NativeUiStructureProtocol.Task(NativeUiStructureProtocol.Status.KNOWN,0,30,1,NativeUiStructureProtocol.Unit.EXPLICIT_TEXT_POINTS),new NativeUiReadyDiagnostics.Result(NativeUiReadyDiagnostics.Idle.IDLE_OBSERVED,1,0,0,0,0,0,0,0),null,true);}
 @Test public void boundModeRoundTripHasTypedProvenance(){var r=report();String wire=NativeUiStructureProtocol.encode(r);assertTrue(wire.startsWith("UIS4|"));assertEquals(36,wire.split("\\|",-1).length);var parsed=NativeUiStructureProtocol.parse(wire,N,90,1000,300,true,false,true);assertEquals(r,parsed);assertTrue(parsed.structureBound());}
 @Test public void oldModeAndOtherVersionsCannotMasqueradeAsBound(){String s=NativeUiStructureProtocol.encode(report());assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s,N,90,1000,300,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s.replace("UIS4","UIS2"),N,90,1000,300,true,false,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s,N,90,1000,300,false,false,true));assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse(s,N,90,1000,300,true,true,true));}
 @Test public void boundUsesOldLimit(){assertThrows(IllegalArgumentException.class,()->NativeUiStructureProtocol.parse("A".repeat(4097),N,90,1000,300,true,false,true));}
 @Test public void provenanceAndCountersShareFinalFence(){var r=report();String good=new UiStructurePublication(r,true,1000).publish(300,true,true,true);assertTrue(good.contains("counterBinding=STRUCTURE_BOUND_CN_EXPLICIT_POINTS"));assertTrue(good.contains("READING=KNOWN n=0 d=30"));for(String s:new String[]{new UiStructurePublication(r,true,1000).publish(300,false,true,true),new UiStructurePublication(r,true,1000).publish(300,true,false,true),new UiStructurePublication(r,true,1000).publish(300,true,true,false),new UiStructurePublication(r,false,1000).publish(300,true,true,true),new UiStructurePublication(r,true,20000).publish(15101,true,true,true),new UiStructurePublication(r,true,300).publish(300,true,true,true)}){assertFalse(s.contains("counterBinding="));assertFalse(s.contains("KNOWN n="));assertTrue(s.contains("publicationFence=REJECTED_AT_APPEND"));}}
 @Test public void legacyConstructorsHaveNoBoundProvenance(){var r=report();var old=new NativeUiStructureProtocol.Report(r.nonce(),r.started(),r.acquired(),r.finished(),r.reason(),r.cleanup(),r.nodeCount(),r.charCount(),r.windowId(),r.displayId(),r.left(),r.top(),r.right(),r.bottom(),r.rotationBefore(),r.rotationAfter(),r.search(),r.reading(),r.readiness());assertFalse(old.structureBound());assertTrue(NativeUiStructureProtocol.encode(old).startsWith("UIS2|"));assertFalse(new UiStructurePublication(old,true,1000).publish(300,true,true,true).contains("counterBinding="));}
 @Test public void fixedReaderSelectsOnlyCompiledBoundMode()throws Exception{String rel="app/src/main/java/com/aliothmoon/maafw/once/AndroidUiStructureReader.java";Path path=Path.of(System.getProperty("staging.root","."),rel);if(!Files.exists(path))path=Path.of("..",rel);String s=Files.readString(path);assertTrue(s.contains("ReadOnlyCheckpoint.CURRENT == ReadOnlyCheckpoint.UI_BOUND_POINTS_V53"));assertTrue(s.contains("command[command.length - 1] = \"BOUND_POINTS_V53\";"));assertTrue(s.contains("fieldMode || boundMode, fieldMode, boundMode"));}
 @Test public void boundConstructorStillRequiresReadiness(){var r=report();assertThrows(IllegalArgumentException.class,()->new NativeUiStructureProtocol.Report(r.nonce(),r.started(),r.acquired(),r.finished(),r.reason(),r.cleanup(),r.nodeCount(),r.charCount(),r.windowId(),r.displayId(),r.left(),r.top(),r.right(),r.bottom(),r.rotationBefore(),r.rotationAfter(),r.search(),r.reading(),null,null,true));}
 @Test public void compactRecordGuardUsesExplicitMethodWithoutRemovingValidation()throws Exception{String rel="app/src/main/java/com/aliothmoon/maafw/once/NativeUiStructureProtocol.java";Path path=Path.of(System.getProperty("staging.root","."),rel);if(!Files.exists(path))path=Path.of("..",rel);String s=Files.readString(path);assertTrue(s.contains("validateBoundProjection(structureBound, readiness, fieldDiagnostics);"));assertTrue(s.contains("private static void validateBoundProjection(boolean structureBound,"));assertTrue(s.contains("if (structureBound && (readiness == null || fieldDiagnostics != null)) throw invalid();"));}
}
